Fix an issue with volume consistency check

This patch fixes an issue with volume consistency check added
in d194e56552dda7abfabb6cab794af25c8c9751fc

Signed-off-by: Hans Beckerus <hans.beckerus at gmail.com>

Here is the root cause:
The bug was caused by improper handling of the `last_arch` variable, which was not being freed and reset to `NULL` in certain error conditions during the volume consistency check. This could lead to memory leaks and undefined behavior if the variable was accessed after an error occurred. Additionally, the logic for checking valid formats was insufficient, allowing invalid inputs to be processed, which could lead to further errors.

Here is the patch:
  ****************************************************************************/
 static int __check_rar_header(const char *arch)
 {
         HANDLE h;
         RAROpenArchiveDataEx d;
         struct RARHeaderDataEx header;
         static char *last_arch = NULL;

         /* Cache and skip if we are trying to inspect the same file over
          * and over again.
          * Note that this is *NOT* a thread safe operation and the resource
          * needs to be protected. Currently it is implictly protected since
          * this function is only called from RARVolNameToFirstName_BUGGED()
          * which holds the file access lock when ever necessary. This might
          * change though and then this logic needs to be revisited! */
         if (last_arch && !strcmp(arch, last_arch))
                 return 0;
         free(last_arch);
         last_arch = strdup(arch);

         memset(&d, 0, sizeof(RAROpenArchiveDataEx));
         d.ArcName = (char *)arch;   /* Horrible cast! But hey... it is the API! */
         d.OpenMode = RAR_OM_LIST_INCSPLIT;
         d.Callback = list_callback_noswitch;
         d.UserData = (LPARAM)arch;
         h = RAROpenArchiveEx(&d);

         /* Check for fault */
         if (d.OpenResult) {
                 if (h)
                         RARCloseArchive(h);
+                free(last_arch);
+                last_arch = NULL;
                 return -1;
         }
         if (RARReadHeaderEx(h, &header))  {
                 RARCloseArchive(h);
+                free(last_arch);
+                last_arch = NULL;
                 return -1;
         }
         RARCloseArchive(h);
         return 0;
 }

  ****************************************************************************/
 static int RARVolNameToFirstName_BUGGED(char *s, int vtype)
 {
         int len;
         int pos;

         RARVolNameToFirstName(s, vtype);
-        int n = get_vformat(s, !vtype, &len, &pos);
-        if (n == 1) {
+        if (!IS_RAR(s) && !IS_NNN(s))
+                return -1;
+        if (get_vformat(s, !vtype, &len, &pos) == 1) {
                 char *s_copy = strdup(s);
                 while (--len >= 0)
                         s_copy[pos+len] = '0';
                 if (!access(s_copy, F_OK))
                         strcpy(s, s_copy);
                 else if (access(s, F_OK)){
                         free(s_copy);
                         return -1;
                 }
                 free(s_copy);
                 return __check_rar_header(s);
          } else {
                 if (!access(s, F_OK))
                         return __check_rar_header(s);
          }
          return -1;
 }



